@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<div class="notepad-container">
    <textarea @bind="_content" @bind:event="oninput" @bind:after="OnContentChanged"
              placeholder="Type your notes here…"
              rows="12"></textarea>

    <div class="notepad-toolbar">
        <div class="notepad-status">
            @if (_lastSavedAt is not null)
            {
                <span>Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
            }
        </div>
        <div class="notepad-actions">
            <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
            <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
        </div>
    </div>
</div>

@code {
    private string _content = string.Empty;
    private string _savedContent = string.Empty;
    private DateTime? _lastSavedAt;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            var saved = await _interop.InitializeAsync(_dotNetRef);
            if (!string.IsNullOrEmpty(saved))
            {
                _content = saved;
                _savedContent = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async Task OnContentChanged()
    {
        if (_content != _savedContent && _interop is not null)
        {
            // Mark dirty in JS so beforeunload fires
            var module = await JS.InvokeAsync<IJSObjectReference>("import", NotepadInterop.ModulePath);
            await module.InvokeVoidAsync("markDirty");
            await module.DisposeAsync();
        }
    }

    private void AutoSaveCallback(object? state)
    {
        _ = InvokeAsync(async () =>
        {
            if (_content != _savedContent)
            {
                await SaveContentAsync();
                StateHasChanged();
            }
        });
    }

    private async Task SaveNowAsync()
    {
        await SaveContentAsync();
    }

    private async Task SaveContentAsync()
    {
        if (_interop is not null)
        {
            await _interop.SaveAsync(_content);
            _savedContent = _content;
            _lastSavedAt = DateTime.Now;
        }
    }

    private async Task ClearAsync()
    {
        if (_interop is not null)
        {
            await _interop.ClearAsync();
            _content = string.Empty;
            _savedContent = string.Empty;
            _lastSavedAt = null;
        }
    }

    [JSInvokable]
    public async Task OnAutoSave()
    {
        await InvokeAsync(async () =>
        {
            await SaveContentAsync();
            StateHasChanged();
        });
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }

        _dotNetRef?.Dispose();
    }
}

